            'handleClick',
            'handleDragStart',
            'handleDragOver',
            'handleDragEnd',
            'handleDrop',
        ]);
    }

    componentDidMount() {
        if (this.props.needHighlight) {
            this.addHighlightTimer = setTimeout(() => {
                this.setState({
                    highlight: true,
                });
            }, 1);
            this.removeHighlightTimer = setTimeout(() => {
                this.setState({
                    highlight: false,
                });
            }, 201);
        }
