                onDragOver(item.value);
            }
        }
    }

    handleDragEnd() {
        const { onDragEnd } = this.props;
        onDragEnd();
    }

    handleDrop(e) {
        e.preventDefault();

        const { onDrop, item, panelPosition, dragValue } = this.props;
        onDrop(panelPosition, dragValue, item.value, this.dragGap);
    }

